// tsr_xrt_kernel.sv — Alveo XRT platform adapter around tsr_core: a Vitis RTL kernel body with
// per-channel AXI4 ports as packed [NUM_CH] vectors. The packaged kernels (tsr_u200_k1,
// tsr_u200_k4, generated by gen_tops.py) instantiate it with fixed parameters and named ports
// (m_axi_ch<c>_*); simulation (tb/platform, tb/fastreplay --top kernel) uses it directly.
//
// Owner: adapter agent (docs/platform-u200.md; docs/design EX §9). The host uses register
// access only (`ap_ctrl_none`, EX §9.1); there is no start sequencer or interrupt.
//
// Kernel interface (the lead's kernel contract, docs/platform-u200.md §1, without `interrupt`):
//   ap_clk, ap_rst_n (active low, synchronous): the core clock and the adapter's reset;
//   ap_clk_2, ap_rst_n_2: the control core's clock and reset (tsr_core clk_rv / rst_rv_n, CC §11.1,
//   §13.3; the link requests 166.7 MHz, hw/u200/k*.cfg); s_axi_control (AXI4-Lite, 32-bit data,
//   13-bit address; tsr_xrt_ctrl has the register map); m_axi_*[c], c < NUM_CH (AXI4, 512-bit
//   data, 64-bit address, 4-bit ID; tsr_xrt_axi_bridge has the mapping of the core's channel c
//   memory port).
// Memory gate (EX §9.2 MEM_EN): while ADAPTER_CTRL.MEM_EN = 0 the core's read / write requests
//   and write data beats are held at the bridge inputs (valid not forwarded, ready 0: nothing is
//   dropped) and an offered request sets ADAPTER_STATUS.REQ_HELD; responses of transactions
//   already issued always pass. A registered copy of MEM_EN per channel drives the gate (it opens
//   one cycle after the bases are latched, so a bridge never sees a request with a stale base).
//   Limit (W4-B review): MEM_EN falling in the middle of a write burst whose request already passed
//   also holds that burst's remaining data beats until MEM_EN is set again. The host clears MEM_EN
//   only with the core idle (EX §9.2), so no burst is in flight; letting the data of accepted requests
//   through needs a count of accepted requests against data bursts (data may lead its request) and a
//   kernel bench with firmware traffic (W5), neither of which exists yet.
// plat_err_i (EX §9.3) = ADAPTER_STATUS bits 0..2 or the error count != 0 (tsr_xrt_ctrl).
// Parameters: the tsr_core parameters (same names and defaults, passed through; RST_PIPE = the
// core's own reset register stages, replicated per block inside the core), AXI_SLICES (register
// slices per AXI channel of every bridge, >= 1) and RST_STAGES (the adapter's core reset pipeline,
// >= 2; tsr_xrt_reset). The core's blocks leave reset RST_STAGES - 2 + RST_PIPE cycles after the
// bridges and the control bridge (never before them).
// Reset requirement (docs/platform-u200.md §5): ap_rst_n low for at least max(3, RST_PIPE + 1)
// cycles (4 in the U200 tops, RST_PIPE 3). With L low cycles the bridges leave reset L + 2 edges
// after ap_rst_n falls, while the core's outputs go quiet only RST_PIPE + 2 edges after it: a
// shorter pulse lets a request of the pre-reset core through a released bridge. The core itself
// then sees its rst_n low for L + RST_STAGES - 2 >= RST_PIPE + 1 cycles. Checked in simulation.
//
//   ap_rst_n -> tsr_xrt_reset -+-> tsr_xrt_ctrl  <-> s_axi_control
//                              |       |  CSR port, latched bases, MEM_EN, events, plat_err
//                              +-> tsr_core  <- ap_clk_2 / ap_rst_n_2 (clk_rv / rst_rv_n)
//                              |       |  memory port c -> MEM_EN gate
//                              +-> tsr_xrt_axi_bridge[c] <-> m_axi_*[c]

module tsr_xrt_kernel
  import tsr_pkg::*;
#(
  parameter int unsigned     NUM_CH         = TSR_DEF_NUM_CH,
  parameter int unsigned     BEAT_BITS      = TSR_DEF_BEAT_BITS,
  parameter int unsigned     LANES          = TSR_DEF_LANES,
  parameter int unsigned     T_MAX          = TSR_DEF_T_MAX,
  parameter int unsigned     K_MAX          = TSR_DEF_K_MAX,
  parameter int unsigned     SPM_BYTES      = TSR_DEF_SPM_BYTES,
  parameter int unsigned     VL             = TSR_DEF_VL,
  parameter int unsigned     NSREG          = TSR_DEF_NSREG,
  parameter int unsigned     RD_OUTSTANDING = TSR_DEF_RD_OUTSTANDING,
  parameter longint unsigned CH_BYTES       = TSR_DEF_CH_BYTES,
  parameter int unsigned     ADDR_BEAT_W    = TSR_DEF_ADDR_BEAT_W,
  parameter bit              HAS_MVM        = 1'b1,
  parameter int unsigned     SPM_RD_LAT     = TSR_DEF_SPM_RD_LAT,
  parameter int unsigned     MVM_WS_FIFO    = TSR_DEF_WS_FIFO_BEATS,
  parameter int unsigned     MVM_BC_PIPE    = TSR_DEF_MVM_BC_PIPE,
  parameter bit              DDR_LOCAL_PIPE = 1'b0,
  parameter bit              LOCAL_INTERMEDIATES = 1'b0,
  parameter bit              LOCAL_SOFTCAP = 1'b0,
  parameter bit              LOCAL_SCALE = 1'b0,
  parameter bit              RV_LOCAL_TRANSPORT = 1'b0,
  parameter bit              XSLR_REG       = 1'b0,
  parameter bit              FAST_CLK       = 1'b0,   // the cycle-changing stages of the 250 MHz core clock (tsr_core)
  // Optional blocks (tsr_core): the vector unit, attention (KVST on the DMA, ATTQK / ATTPV in the clusters and
  // the gather) and the DB block's trace writer and dispatch history. tsr_u200_k4 builds none of them.
  parameter bit              HAS_VU         = 1'b1,
  parameter bit              HAS_ATT        = HAS_MVM,
  parameter bit              HAS_TRW        = 1'b1,
  parameter int unsigned     HIST_DEPTH     = tsr_tables_pkg::TSR_HIST_DEPTH,
  parameter bit              MVM_GATHER_PAIR = 1'b0,
  parameter int unsigned     MVM_GATHER_FLITS = 1,
  parameter int unsigned     MVM_RES_PIPE   = TSR_DEF_MVM_RES_PIPE,
  parameter int unsigned     MVM_ACT_RD_LAT = TSR_DEF_ACT_RD_LAT,
  parameter int unsigned     MVM_MAC_LAT    = TSR_DEF_MAC_LAT,
  parameter int unsigned     MVM_MUL_LAT    = TSR_DEF_FMUL_LAT,
  parameter int unsigned     MVM_ADD_LAT    = TSR_DEF_FADD_LAT,
  parameter int unsigned     MVM_WS_RD_LAT  = TSR_DEF_WS_RD_LAT,
  parameter int unsigned     RST_PIPE       = 0,
  // the vector unit's lane knobs (VU §7.10: 16 / 8 on k4, 8 / 4 on k1; results unchanged)
  parameter int unsigned     VU_FRONT_LANES = tsr_tables_pkg::TSR_VU_FRONT_LANES,
  parameter int unsigned     VU_EXP_LANES   = tsr_tables_pkg::TSR_VU_FRONT_LANES,
  parameter int unsigned     VU_BACK_LANES  = tsr_tables_pkg::TSR_VU_BACK_LANES,
  // register stages on each side of the VU lanes (k4: 2, the lanes sit in SLR0; k1: 0)
  parameter int unsigned     VU_LANE_PIPE   = 0,
  // adapter
  parameter int unsigned     AXI_SLICES     = 2,
  parameter int unsigned     RST_STAGES     = 3
) (
  input  logic                                 ap_clk,
  input  logic                                 ap_rst_n,
  input  logic                                 ap_clk_2,
  input  logic                                 ap_rst_n_2,

  // ---- s_axi_control ----
  input  logic                                 s_axi_control_awvalid,
  output logic                                 s_axi_control_awready,
  input  logic [12:0]                          s_axi_control_awaddr,
  input  logic                                 s_axi_control_wvalid,
  output logic                                 s_axi_control_wready,
  input  logic [31:0]                          s_axi_control_wdata,
  input  logic [3:0]                           s_axi_control_wstrb,
  output logic                                 s_axi_control_bvalid,
  input  logic                                 s_axi_control_bready,
  output logic [1:0]                           s_axi_control_bresp,
  input  logic                                 s_axi_control_arvalid,
  output logic                                 s_axi_control_arready,
  input  logic [12:0]                          s_axi_control_araddr,
  output logic                                 s_axi_control_rvalid,
  input  logic                                 s_axi_control_rready,
  output logic [31:0]                          s_axi_control_rdata,
  output logic [1:0]                           s_axi_control_rresp,

  // ---- m_axi, one per channel ----
  output logic [NUM_CH-1:0]                    m_axi_awvalid,
  input  logic [NUM_CH-1:0]                    m_axi_awready,
  output logic [NUM_CH-1:0][63:0]              m_axi_awaddr,
  output logic [NUM_CH-1:0][7:0]               m_axi_awlen,
  output logic [NUM_CH-1:0][2:0]               m_axi_awsize,
  output logic [NUM_CH-1:0][1:0]               m_axi_awburst,
  output logic [NUM_CH-1:0]                    m_axi_awlock,
  output logic [NUM_CH-1:0][3:0]               m_axi_awcache,
  output logic [NUM_CH-1:0][2:0]               m_axi_awprot,
  output logic [NUM_CH-1:0][3:0]               m_axi_awqos,
  output logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_awid,
  output logic [NUM_CH-1:0]                    m_axi_wvalid,
  input  logic [NUM_CH-1:0]                    m_axi_wready,
  output logic [NUM_CH-1:0][BEAT_BITS-1:0]     m_axi_wdata,
  output logic [NUM_CH-1:0][BEAT_BITS/8-1:0]   m_axi_wstrb,
  output logic [NUM_CH-1:0]                    m_axi_wlast,
  input  logic [NUM_CH-1:0]                    m_axi_bvalid,
  output logic [NUM_CH-1:0]                    m_axi_bready,
  input  logic [NUM_CH-1:0][1:0]               m_axi_bresp,
  input  logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_bid,
  output logic [NUM_CH-1:0]                    m_axi_arvalid,
  input  logic [NUM_CH-1:0]                    m_axi_arready,
  output logic [NUM_CH-1:0][63:0]              m_axi_araddr,
  output logic [NUM_CH-1:0][7:0]               m_axi_arlen,
  output logic [NUM_CH-1:0][2:0]               m_axi_arsize,
  output logic [NUM_CH-1:0][1:0]               m_axi_arburst,
  output logic [NUM_CH-1:0]                    m_axi_arlock,
  output logic [NUM_CH-1:0][3:0]               m_axi_arcache,
  output logic [NUM_CH-1:0][2:0]               m_axi_arprot,
  output logic [NUM_CH-1:0][3:0]               m_axi_arqos,
  output logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_arid,
  input  logic [NUM_CH-1:0]                    m_axi_rvalid,
  output logic [NUM_CH-1:0]                    m_axi_rready,
  input  logic [NUM_CH-1:0][BEAT_BITS-1:0]     m_axi_rdata,
  input  logic [NUM_CH-1:0][1:0]               m_axi_rresp,
  input  logic [NUM_CH-1:0]                    m_axi_rlast,
  input  logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0]  m_axi_rid
);

  // -------------------------------------------------------------------------------------------
  // Reset distribution: per channel one copy for each of the bridge's reset parts
  // (tsr_xrt_axi_bridge header): [0] request slices, [1] AXI-side stages, [2] read path,
  // [3] write path, [4 +: CNT_RST] read counters, [4 + CNT_RST +: CNT_RST] write counters
  // -------------------------------------------------------------------------------------------
  localparam int unsigned CNT_RST = 4;                  // counter reset copies (ID groups of 4)
  localparam int unsigned BR_RST  = 4 + 2 * CNT_RST;
  logic                          rst_ctrl_n, rst_core_n;
  logic [NUM_CH-1:0][BR_RST-1:0] rst_ch_n;

  tsr_xrt_reset #(.N_CH(NUM_CH), .CH_COPIES(BR_RST), .CORE_STAGES(RST_STAGES)) u_rst (
    .clk(ap_clk), .rst_in_n(ap_rst_n), .rst_ctrl_n, .rst_ch_n, .rst_core_n
  );

`ifndef SYNTHESIS
  // Simulation check of the minimum reset pulse (header): every low phase of ap_rst_n must last
  // RST_MIN_LOW cycles or more (3: the bridges' AXI-side flops are reset 3 edges after ap_rst_n
  // falls; RST_PIPE + 1: the pre-reset core must be quiet before the bridges leave reset).
  localparam int unsigned RST_MIN_LOW = (RST_PIPE + 1 > 3) ? RST_PIPE + 1 : 3;
  int unsigned rst_low_q;                 // ap_rst_n low cycles so far (saturating at RST_MIN_LOW)
  initial rst_low_q = 0;
  always @(posedge ap_clk) begin
    if (!ap_rst_n) begin
      if (rst_low_q < RST_MIN_LOW) rst_low_q <= rst_low_q + 32'd1;
    end else begin
      if (rst_low_q != 0 && rst_low_q < RST_MIN_LOW)
        $error("%m: ap_rst_n low for %0d cycles, minimum %0d (docs/platform-u200.md section 5)",
               rst_low_q, RST_MIN_LOW);
      rst_low_q <= 0;
    end
  end
`endif

  // -------------------------------------------------------------------------------------------
  // Control bridge
  // -------------------------------------------------------------------------------------------
  logic                    csr_valid, csr_ready, csr_we;
  logic [TSR_CSR_AW-1:0]   csr_addr;
  logic [31:0]             csr_wdata, csr_rdata;
  logic [NUM_CH-1:0][63:0] ch_base;
  logic [NUM_CH-1:0]       ev_rresp_err, ev_bresp_err, ev_unexpected;
  logic                    mem_en, req_held, plat_err;

  tsr_xrt_ctrl #(.NUM_CH(NUM_CH)) u_ctrl (
    .clk(ap_clk), .rst_n(rst_ctrl_n),
    .s_awvalid(s_axi_control_awvalid), .s_awready(s_axi_control_awready), .s_awaddr(s_axi_control_awaddr),
    .s_wvalid(s_axi_control_wvalid), .s_wready(s_axi_control_wready), .s_wdata(s_axi_control_wdata),
    .s_wstrb(s_axi_control_wstrb),
    .s_bvalid(s_axi_control_bvalid), .s_bready(s_axi_control_bready), .s_bresp(s_axi_control_bresp),
    .s_arvalid(s_axi_control_arvalid), .s_arready(s_axi_control_arready), .s_araddr(s_axi_control_araddr),
    .s_rvalid(s_axi_control_rvalid), .s_rready(s_axi_control_rready), .s_rdata(s_axi_control_rdata),
    .s_rresp(s_axi_control_rresp),
    .csr_valid, .csr_ready, .csr_we, .csr_addr, .csr_wdata, .csr_rdata,
    .ch_base, .mem_en, .ev_req_held(req_held), .plat_err, .ev_rresp_err, .ev_bresp_err, .ev_unexpected
  );

  // -------------------------------------------------------------------------------------------
  // Core
  // -------------------------------------------------------------------------------------------
  logic [NUM_CH-1:0]                   rd_req_valid, rd_req_ready, rd_rsp_valid, rd_rsp_ready, rd_rsp_last;
  logic [NUM_CH-1:0][ADDR_BEAT_W-1:0]  rd_req_addr, wr_req_addr;
  logic [NUM_CH-1:0][TSR_LEN_W-1:0]    rd_req_len, wr_req_len;
  logic [NUM_CH-1:0][TSR_MEM_ID_W-1:0] rd_req_id, rd_rsp_id, wr_req_id, wr_rsp_id;
  logic [NUM_CH-1:0][BEAT_BITS-1:0]    rd_rsp_data, wr_dat_data;
  logic [NUM_CH-1:0][BEAT_BITS/32-1:0] wr_dat_mask;
  logic [NUM_CH-1:0]                   wr_req_valid, wr_req_ready, wr_dat_valid, wr_dat_ready, wr_dat_last;
  logic [NUM_CH-1:0]                   wr_rsp_valid, wr_rsp_ready;
  // the bridges' side of the MEM_EN gate
  logic [NUM_CH-1:0]                   g_rd_req_valid, g_rd_req_ready, g_wr_req_valid, g_wr_req_ready;
  logic [NUM_CH-1:0]                   g_wr_dat_valid, g_wr_dat_ready;
  logic [NUM_CH-1:0]                   mem_en_q;
  logic [NUM_CH-1:0]                   held_c;

  for (genvar c = 0; c < NUM_CH; c++) begin : g_gate
    always_ff @(posedge ap_clk) begin
      if (!rst_ch_n[c][0]) mem_en_q[c] <= 1'b0;
      else                 mem_en_q[c] <= mem_en;
    end
    assign g_rd_req_valid[c] = rd_req_valid[c] && mem_en_q[c];
    assign rd_req_ready[c]   = g_rd_req_ready[c] && mem_en_q[c];
    assign g_wr_req_valid[c] = wr_req_valid[c] && mem_en_q[c];
    assign wr_req_ready[c]   = g_wr_req_ready[c] && mem_en_q[c];
    assign g_wr_dat_valid[c] = wr_dat_valid[c] && mem_en_q[c];
    assign wr_dat_ready[c]   = g_wr_dat_ready[c] && mem_en_q[c];
    assign held_c[c] = !mem_en_q[c] && (rd_req_valid[c] || wr_req_valid[c] || wr_dat_valid[c]);
  end

  // XSLR_REG: in the K4 floorplan the channel arbiters sit in all three SLRs and u_ctrl in one of them, so each
  // channel's held event passes two register stages before the OR: REQ_HELD is set 2 cycles later. The stages
  // have no reset (like the XSLR_REG stages in tsr_core_dp): they start at 0, and the core's reset clears
  // the request valids at their input, so they are clear after 2 cycles of reset.
  logic [NUM_CH-1:0] held_o;
  if (XSLR_REG) begin : g_hx
    (* shreg_extract = "no" *) logic [1:0][NUM_CH-1:0] hx_q;
    initial hx_q = '0;
    always @(posedge ap_clk) begin        // not always_ff: the initial block writes it too
      hx_q[0] <= held_c;
      hx_q[1] <= hx_q[0];
    end
    assign held_o = hx_q[1];
  end else begin : g_hx0
    assign held_o = held_c;
  end
  assign req_held = |held_o;

  logic host_irq;                         // EX §9.3: not connected on the U200
  wire  unused_host_irq = &{1'b0, host_irq};

  tsr_core #(
    .NUM_CH(NUM_CH), .BEAT_BITS(BEAT_BITS), .LANES(LANES), .T_MAX(T_MAX), .K_MAX(K_MAX),
    .SPM_BYTES(SPM_BYTES), .VL(VL), .NSREG(NSREG),
    .RD_OUTSTANDING(RD_OUTSTANDING), .CH_BYTES(CH_BYTES), .ADDR_BEAT_W(ADDR_BEAT_W),
    .HAS_MVM(HAS_MVM), .SPM_RD_LAT(SPM_RD_LAT),
    .HAS_VU(HAS_VU), .HAS_ATT(HAS_ATT), .HAS_TRW(HAS_TRW), .HIST_DEPTH(HIST_DEPTH),
    .LOCAL_INTERMEDIATES(LOCAL_INTERMEDIATES), .LOCAL_SCALE(LOCAL_SCALE), .LOCAL_SOFTCAP(LOCAL_SOFTCAP), .RV_LOCAL_TRANSPORT(RV_LOCAL_TRANSPORT), .XSLR_REG(XSLR_REG), .FAST_CLK(FAST_CLK),
    .MVM_WS_FIFO(MVM_WS_FIFO), .MVM_BC_PIPE(MVM_BC_PIPE), .MVM_RES_PIPE(MVM_RES_PIPE), .MVM_GATHER_PAIR(MVM_GATHER_PAIR), .MVM_GATHER_FLITS(MVM_GATHER_FLITS), .DDR_LOCAL_PIPE(DDR_LOCAL_PIPE),
    .MVM_ACT_RD_LAT(MVM_ACT_RD_LAT), .MVM_MAC_LAT(MVM_MAC_LAT), .MVM_MUL_LAT(MVM_MUL_LAT),
    .MVM_ADD_LAT(MVM_ADD_LAT), .MVM_WS_RD_LAT(MVM_WS_RD_LAT), .RST_PIPE(RST_PIPE),
    .VU_FRONT_LANES(VU_FRONT_LANES), .VU_EXP_LANES(VU_EXP_LANES), .VU_BACK_LANES(VU_BACK_LANES), .VU_LANE_PIPE(VU_LANE_PIPE)
  ) u_core (
    // the control core on ap_clk_2 / ap_rst_n_2 (CC §13.3); the clk_rv domain's own reset is
    // rst_core_n through tsr_ctrl's synchroniser, ap_rst_n_2 is AND-ed into the Ibex / DM resets
    .clk(ap_clk), .rst_n(rst_core_n), .clk_rv(ap_clk_2), .rst_rv_n(ap_rst_n_2),
    .plat_err_i(plat_err), .host_irq_o(host_irq),
    .csr_valid, .csr_ready, .csr_we, .csr_addr, .csr_wdata, .csr_rdata,
    .m_rd_req_valid(rd_req_valid), .m_rd_req_ready(rd_req_ready), .m_rd_req_addr(rd_req_addr),
    .m_rd_req_len(rd_req_len), .m_rd_req_id(rd_req_id),
    .m_rd_rsp_valid(rd_rsp_valid), .m_rd_rsp_ready(rd_rsp_ready), .m_rd_rsp_data(rd_rsp_data),
    .m_rd_rsp_id(rd_rsp_id), .m_rd_rsp_last(rd_rsp_last),
    .m_wr_req_valid(wr_req_valid), .m_wr_req_ready(wr_req_ready), .m_wr_req_addr(wr_req_addr),
    .m_wr_req_len(wr_req_len), .m_wr_req_id(wr_req_id),
    .m_wr_dat_valid(wr_dat_valid), .m_wr_dat_ready(wr_dat_ready), .m_wr_dat_data(wr_dat_data), .m_wr_dat_mask(wr_dat_mask),
    .m_wr_dat_last(wr_dat_last),
    .m_wr_rsp_valid(wr_rsp_valid), .m_wr_rsp_ready(wr_rsp_ready), .m_wr_rsp_id(wr_rsp_id)
  );

  // -------------------------------------------------------------------------------------------
  // Channel bridges
  // -------------------------------------------------------------------------------------------
  for (genvar c = 0; c < NUM_CH; c++) begin : g_ch
    tsr_xrt_axi_bridge #(
      .ADDR_BEAT_W(ADDR_BEAT_W), .BEAT_BITS(BEAT_BITS), .SLICES(AXI_SLICES), .CNT_RST(CNT_RST)
    ) u_br (
      .clk(ap_clk), .rst_n(rst_ch_n[c][0]), .rst_axi_n(rst_ch_n[c][1]), .rst_rd_n(rst_ch_n[c][2]),
      .rst_wr_n(rst_ch_n[c][3]), .rst_rdc_n(rst_ch_n[c][4 +: CNT_RST]),
      .rst_wrc_n(rst_ch_n[c][4 + CNT_RST +: CNT_RST]), .base(ch_base[c]),
      .c_rd_req_valid(g_rd_req_valid[c]), .c_rd_req_ready(g_rd_req_ready[c]), .c_rd_req_addr(rd_req_addr[c]),
      .c_rd_req_len(rd_req_len[c]), .c_rd_req_id(rd_req_id[c]),
      .c_rd_rsp_valid(rd_rsp_valid[c]), .c_rd_rsp_ready(rd_rsp_ready[c]), .c_rd_rsp_data(rd_rsp_data[c]),
      .c_rd_rsp_id(rd_rsp_id[c]), .c_rd_rsp_last(rd_rsp_last[c]),
      .c_wr_req_valid(g_wr_req_valid[c]), .c_wr_req_ready(g_wr_req_ready[c]), .c_wr_req_addr(wr_req_addr[c]),
      .c_wr_req_len(wr_req_len[c]), .c_wr_req_id(wr_req_id[c]),
      .c_wr_dat_valid(g_wr_dat_valid[c]), .c_wr_dat_ready(g_wr_dat_ready[c]), .c_wr_dat_data(wr_dat_data[c]), .c_wr_dat_mask(wr_dat_mask[c]),
      .c_wr_dat_last(wr_dat_last[c]),
      .c_wr_rsp_valid(wr_rsp_valid[c]), .c_wr_rsp_ready(wr_rsp_ready[c]), .c_wr_rsp_id(wr_rsp_id[c]),
      .m_axi_awvalid(m_axi_awvalid[c]), .m_axi_awready(m_axi_awready[c]), .m_axi_awaddr(m_axi_awaddr[c]),
      .m_axi_awlen(m_axi_awlen[c]), .m_axi_awsize(m_axi_awsize[c]), .m_axi_awburst(m_axi_awburst[c]),
